    ('DATA_CLASSIFICATION_REGULATORY', 'data_classification_regulatory', 'Data Classification', '["AWS", "SNOWFLAKE", "DENODO", "COLLIBRA"]', 'MANDATORY', 1, 'privacy', 'Regulatory-driven data classification. Holds the GOVERNING category - the one whose technical controls are most prescriptive - resolved by documented precedence. Where several categories apply, the full set is recorded in CONTROL.REGULATORY_SCOPE, because a Snowflake tag holds only one value.', 'controlled_vocabulary', NULL, NULL, 'inherit', 'more_restrictive_only', '["NONE", "PII", "SPII", "PHI", "PCI"]', '["dynamic_masking", "privacy_reporting", "dsar_fulfilment", "audit_evidence", "auto_classification", "pci_scoping"]', 'PRIVACY_OFFICE', '1.0.0', 'ACTIVE', NULL, '2.0.0'),
    ('DATA_PRODUCT', 'data_product', 'Data Product', '["SNOWFLAKE", "DENODO", "COLLIBRA"]', NULL, 2, 'business', 'Named, versioned, independently consumable data product. Maps 1:1 to a schema, which is the publication boundary. Distinct from `application`: one application can publish several data products.', 'reference_data', '^dp-[a-z0-9][a-z0-9-]{2,48}$', 'REF_DATA_PRODUCT', 'inherit', 'none', NULL, '["data_mesh", "discovery", "lineage", "sla_management", "consumer_contract"]', 'DOMAIN_COUNCIL', '1.0.0', 'ACTIVE', NULL, '2.0.0'),
