    ('SUPPORT_GROUP', 'support_group', 'Ownership', '["AWS", "SNOWFLAKE", "DENODO"]', NULL, 2, 'ownership', 'ITSM queue that owns break/fix. Complements `team`, which names the accountable engineers; support_group names where the ticket actually lands out of hours.', 'reference_data', '^GRP-[A-Z0-9-]{3,48}$', 'REF_SUPPORT_GROUP', 'inherit', 'any', NULL, '["incident_routing", "sla_management", "operational_reporting"]', 'PLATFORM_ENGINEERING', '1.0.0', 'ACTIVE', NULL, '2.0.0'),
