    ('MASKING_REQUIRED', 'masking_required', 'Security', '["SNOWFLAKE"]', NULL, 2, 'security', 'Declares that the column must carry a masking policy. This is DECLARED INTENT; the tag-based policy attachment is ENFORCEMENT. The drift detector reconciles the two, and divergence is the finding that matters most.', 'controlled_vocabulary', NULL, NULL, 'inherit', 'more_restrictive_only', '["NO", "YES"]', '["dynamic_masking", "control_attestation", "drift_detection"]', 'CISO_DATA_SECURITY', '1.0.0', 'ACTIVE', NULL, '2.0.0'),
