-- TAG_CONDITIONAL_RULE
INSERT INTO TAG_CONDITIONAL_RULE (RULE_ID, DESCRIPTION, SEVERITY, OBJECT_TYPES, PREDICATE, THEN_MANDATORY)
SELECT c1, c2, c3, PARSE_JSON(c4)::ARRAY, PARSE_JSON(c5)::OBJECT, PARSE_JSON(c6)::ARRAY
FROM VALUES
    ('CR-001', 'Any column carrying regulated data must declare masking intent, so that declared-versus-enforced drift is detectable for it.', 'CRITICAL', '["COLUMN"]', '{"DATA_CLASSIFICATION_REGULATORY": ["PII", "SPII", "PHI", "PCI"]}', '["MASKING_REQUIRED"]'),
    ('CR-002', 'Cardholder data requires application-layer encryption in addition to Snowflake''s transparent encryption at rest.', 'CRITICAL', '["TABLE", "COLUMN", "STAGE"]', '{"DATA_CLASSIFICATION_REGULATORY": ["PCI"]}', '["ENCRYPTION_REQUIRED"]'),
    ('CR-003', 'RESTRICTED data must declare row-level access intent; confidentiality at this level is rarely satisfied by column masking alone.', 'HIGH', '["TABLE", "VIEW", "MATERIALIZED_VIEW", "DYNAMIC_TABLE"]', '{"DATA_CLASSIFICATION_ENTERPRISE": ["RESTRICTED"]}', '["ROW_ACCESS_REQUIRED"]'),
    ('CR-004', 'Regulated data needs an accountable data owner and a retention class - without both, neither a DSAR nor a purge can be executed.', 'HIGH', '["SCHEMA", "TABLE", "VIEW"]', '{"DATA_CLASSIFICATION_REGULATORY": ["PII", "SPII", "PHI", "PCI"]}', '["DATA_OWNER", "RETENTION_CLASS"]'),
    ('CR-005', 'Personal and health data must declare residency so replication and cross-region sharing can be evaluated before, not after, the fact.', 'HIGH', '["DATABASE", "SCHEMA", "SHARE"]', '{"DATA_CLASSIFICATION_REGULATORY": ["SPII", "PHI", "PCI"]}', '["DATA_RESIDENCY"]'),
    ('CR-006', 'Business-critical objects must publish RPO and RTO for DR planning.', 'MEDIUM', '["DATABASE", "SCHEMA", "TABLE"]', '{"CRITICALITY": ["CRITICAL"]}', '["RPO", "RTO"]'),
    ('CR-007', 'Data leaving the account always needs a named owner, a classification and an explicit distribution scope. There is no version of a share for which this is optional.', 'CRITICAL', '["SHARE"]', '{}', '["SHARING_SCOPE", "DATA_CLASSIFICATION_ENTERPRISE", "DATA_OWNER", "DATA_PRODUCT"]'),
    ('CR-008', 'Production workloads must name an on-call queue and an SLA commitment. An unroutable production incident is the failure this prevents.', 'MEDIUM', '["SCHEMA", "TASK", "PIPE"]', '{"ENVIRONMENT": ["PRD"]}', '["SUPPORT_GROUP", "SLA_TIER"]'),
    ('CR-009', 'Chargeback settlement posts a journal entry, which needs a GL cost centre code; `department` alone is not a posting key.', 'MEDIUM', '["WAREHOUSE", "DATABASE", "SCHEMA"]', '{"COST_ALLOCATION_MODEL": ["CHARGEBACK"]}', '["COST_CENTER"]')
AS v(c1, c2, c3, c4, c5, c6);


-- TAG_POLICY_BINDING
INSERT INTO TAG_POLICY_BINDING (TAG_NAME, TAG_VALUE, POLICY_KIND, POLICY_NAME, DATA_TYPE, ATTACH_MODE, NOTES)
SELECT c1, c2, c3, c4, c5, c6, c7
FROM VALUES
    ('DATA_CLASSIFICATION_ENTERPRISE', NULL, 'MASKING', 'GOVERNANCE.POLICIES.MP_ENTERPRISE_STRING', 'STRING', 'TAG_ATTACHED', 'Bound to data_classification_enterprise only. data_classification_regulatory deliberately carries no attachment of its own - it is read inside the policy body.'),
    ('DATA_CLASSIFICATION_ENTERPRISE', NULL, 'MASKING', 'GOVERNANCE.POLICIES.MP_ENTERPRISE_NUMBER', 'NUMBER', 'TAG_ATTACHED', 'Bound to data_classification_enterprise only. data_classification_regulatory deliberately carries no attachment of its own - it is read inside the policy body.'),
    ('DATA_CLASSIFICATION_ENTERPRISE', NULL, 'MASKING', 'GOVERNANCE.POLICIES.MP_ENTERPRISE_DATE', 'DATE', 'TAG_ATTACHED', 'Bound to data_classification_enterprise only. data_classification_regulatory deliberately carries no attachment of its own - it is read inside the policy body.'),
    ('DATA_CLASSIFICATION_ENTERPRISE', NULL, 'MASKING', 'GOVERNANCE.POLICIES.MP_ENTERPRISE_TIMESTAMP_NTZ', 'TIMESTAMP_NTZ', 'TAG_ATTACHED', 'Bound to data_classification_enterprise only. data_classification_regulatory deliberately carries no attachment of its own - it is read inside the policy body.'),
    ('DATA_CLASSIFICATION_ENTERPRISE', NULL, 'MASKING', 'GOVERNANCE.POLICIES.MP_ENTERPRISE_VARIANT', 'VARIANT', 'TAG_ATTACHED', 'Bound to data_classification_enterprise only. data_classification_regulatory deliberately carries no attachment of its own - it is read inside the policy body.'),
    ('ROW_ACCESS_REQUIRED', 'YES', 'ROW_ACCESS', 'GOVERNANCE.POLICIES.RAP_OPERATING_COMPANY_SCOPE', NULL, 'RECONCILED', 'Applied by a reconciliation task, not by tag attachment, because Snowflake does not support attaching row access policies to tags. The policy binds to the table''s own OPERATING_COMPANY column; a table declaring the tag without that column is reported as CRITICAL rather than skipped.')
AS v(c1, c2, c3, c4, c5, c6, c7);


-- TAG_CONTRADICTION_RULE
INSERT INTO TAG_CONTRADICTION_RULE (RULE_ID, DESCRIPTION, SEVERITY, IF_TAG, IF_VALUES, THEN_TAG, FORBIDDEN_VALUES)
SELECT c1, c2, c3, c4, PARSE_JSON(c5)::ARRAY, c6, PARSE_JSON(c7)::ARRAY
FROM VALUES
    ('XR-001', 'Regulated data cannot be classified PUBLIC or NONE. This combination is almost always a table that was classified before its contents were understood, and it is the single most dangerous state in the estate: the masking policy reads the enterprise classification and lets the data through in clear.', 'CRITICAL', 'DATA_CLASSIFICATION_REGULATORY', '["PII", "SPII", "PHI", "PCI"]', 'DATA_CLASSIFICATION_ENTERPRISE', '["NONE", "PUBLIC"]'),
    ('XR-002', 'RESTRICTED data cannot be shared beyond the enterprise. Caught before a listing is created rather than after it is discovered.', 'CRITICAL', 'DATA_CLASSIFICATION_ENTERPRISE', '["RESTRICTED"]', 'SHARING_SCOPE', '["PARTNER", "PUBLIC_MARKETPLACE"]'),
    ('XR-003', 'Cardholder data must never sit in a training environment. PCI-DSS scope follows the data, and a TRAINING account is not in the assessed CDE.', 'CRITICAL', 'DATA_CLASSIFICATION_REGULATORY', '["PCI"]', 'ENVIRONMENT', '["TRAINING", "DEV"]'),
    ('XR-004', 'A deprecated or archived object cannot carry a live SLA commitment; consumers reading the catalogue would plan against a promise nobody holds.', 'MEDIUM', 'DATA_LIFECYCLE', '["DEPRECATED", "ARCHIVED", "PENDING_PURGE"]', 'SLA_TIER', '["PLATINUM_15M", "GOLD_1H"]')
AS v(c1, c2, c3, c4, c5, c6, c7);


